const std = @import("std");
const rust_ffi = @import("rust_ffi.zig");

pub const CrossPlatformRuntime = struct {
    allocator: std.mem.Allocator,
    config: CrossPlatformConfig,
    cuda_runtime: ?*anyopaque = null,
    vulkan_runtime: ?*anyopaque = null,
    metal_runtime: ?*anyopaque = null,
    dx12_runtime: ?*anyopaque = null,
    webgpu_runtime: ?*anyopaque = null,
    active_backend: Backend,
    initialized: bool = false,

    const Self = @This();

    pub const CrossPlatformConfig = struct {
        cuda_enabled: bool,
        vulkan_enabled: bool,
        metal_enabled: bool,
        dx12_enabled: bool,
        webgpu_enabled: bool,
        spirv_compilation: bool,
        kernel_fusion: bool,
    };

    pub const Backend = enum {
        cuda,
        vulkan,
        metal,
        dx12,
        webgpu,
        cpu_fallback,
    };

    pub fn init(allocator: std.mem.Allocator, config: CrossPlatformConfig) !Self {
        var runtime = Self{
            .allocator = allocator,
            .config = config,
            .active_backend = .cpu_fallback,
        };

        // Detect available backends and initialize the best one
        runtime.active_backend = try runtime.detectBestBackend();

        switch (runtime.active_backend) {
            .cuda => {
                if (config.cuda_enabled) {
                    runtime.cuda_runtime = rust_ffi.init_cuda_runtime();
                }
            },
            .vulkan => {
                if (config.vulkan_enabled) {
                    runtime.vulkan_runtime = rust_ffi.init_vulkan_runtime();
                }
            },
            .metal => {
                if (config.metal_enabled) {
                    runtime.metal_runtime = rust_ffi.init_metal_runtime();
                }
            },
            .dx12 => {
                if (config.dx12_enabled) {
                    runtime.dx12_runtime = rust_ffi.init_dx12_runtime();
                }
            },
            .webgpu => {
                if (config.webgpu_enabled) {
                    runtime.webgpu_runtime = rust_ffi.init_webgpu_runtime();
                }
            },
            .cpu_fallback => {
                // CPU fallback always available
            },
        }

        runtime.initialized = true;
        return runtime;
    }

    pub fn deinit(self: *Self) void {
        if (self.initialized) {
            switch (self.active_backend) {
                .cuda => if (self.cuda_runtime) |runtime| rust_ffi.destroy_cuda_runtime(runtime),
                .vulkan => if (self.vulkan_runtime) |runtime| rust_ffi.destroy_vulkan_runtime(runtime),
                .metal => if (self.metal_runtime) |runtime| rust_ffi.destroy_metal_runtime(runtime),
                .dx12 => if (self.dx12_runtime) |runtime| rust_ffi.destroy_dx12_runtime(runtime),
                .webgpu => if (self.webgpu_runtime) |runtime| rust_ffi.destroy_webgpu_runtime(runtime),
                .cpu_fallback => {},
            }
            self.initialized = false;
        }
    }

    fn detectBestBackend(self: *Self) !Backend {
        // Try backends in order of performance preference
        if (self.config.cuda_enabled and rust_ffi.is_cuda_available()) {
            return .cuda;
        }
        if (self.config.vulkan_enabled and rust_ffi.is_vulkan_available()) {
            return .vulkan;
        }
        if (self.config.metal_enabled and rust_ffi.is_metal_available()) {
            return .metal;
        }
        if (self.config.dx12_enabled and rust_ffi.is_dx12_available()) {
            return .dx12;
        }
        if (self.config.webgpu_enabled and rust_ffi.is_webgpu_available()) {
            return .webgpu;
        }
        return .cpu_fallback;
    }

    pub fn executeKernel(self: *Self, kernel_source: []const u8, params: []const u8) !void {
        if (!self.initialized) return error.NotInitialized;

        switch (self.active_backend) {
            .cuda => {
                if (self.cuda_runtime) |runtime| {
                    rust_ffi.execute_cuda_kernel(runtime, kernel_source.ptr, kernel_source.len, 
                                               params.ptr, params.len);
                }
            },
            .vulkan => {
                if (self.vulkan_runtime) |runtime| {
                    rust_ffi.execute_vulkan_kernel(runtime, kernel_source.ptr, kernel_source.len,
                                                 params.ptr, params.len);
                }
            },
            .metal => {
                if (self.metal_runtime) |runtime| {
                    rust_ffi.execute_metal_kernel(runtime, kernel_source.ptr, kernel_source.len,
                                                params.ptr, params.len);
                }
            },
            .dx12 => {
                if (self.dx12_runtime) |runtime| {
                    rust_ffi.execute_dx12_kernel(runtime, kernel_source.ptr, kernel_source.len,
                                               params.ptr, params.len);
                }
            },
            .webgpu => {
                if (self.webgpu_runtime) |runtime| {
                    rust_ffi.execute_webgpu_kernel(runtime, kernel_source.ptr, kernel_source.len,
                                                 params.ptr, params.len);
                }
            },
            .cpu_fallback => {
                rust_ffi.execute_cpu_kernel(kernel_source.ptr, kernel_source.len,
                                          params.ptr, params.len);
            },
        }
    }

    pub fn compileKernel(self: *Self, rust_source: []const u8) ![]u8 {
        if (!self.initialized) return error.NotInitialized;

        const compiled_size = rust_ffi.get_compiled_kernel_size(rust_source.ptr, rust_source.len);
        var compiled_kernel = try self.allocator.alloc(u8, compiled_size);

        switch (self.active_backend) {
            .cuda => {
                rust_ffi.compile_to_ptx(rust_source.ptr, rust_source.len, 
                                      compiled_kernel.ptr, compiled_kernel.len);
            },
            .vulkan => {
                rust_ffi.compile_to_spirv(rust_source.ptr, rust_source.len,
                                        compiled_kernel.ptr, compiled_kernel.len);
            },
            .metal => {
                rust_ffi.compile_to_msl(rust_source.ptr, rust_source.len,
                                      compiled_kernel.ptr, compiled_kernel.len);
            },
            .dx12 => {
                rust_ffi.compile_to_hlsl(rust_source.ptr, rust_source.len,
                                       compiled_kernel.ptr, compiled_kernel.len);
            },
            .webgpu => {
                rust_ffi.compile_to_wgsl(rust_source.ptr, rust_source.len,
                                       compiled_kernel.ptr, compiled_kernel.len);
            },
            .cpu_fallback => {
                rust_ffi.compile_to_native(rust_source.ptr, rust_source.len,
                                         compiled_kernel.ptr, compiled_kernel.len);
            },
        }

        return compiled_kernel;
    }

    pub fn getBackendInfo(self: *const Self) BackendInfo {
        return BackendInfo{
            .active_backend = self.active_backend,
            .performance_tier = switch (self.active_backend) {
                .cuda => .high,
                .vulkan, .metal, .dx12 => .medium,
                .webgpu => .low,
                .cpu_fallback => .minimal,
            },
            .memory_bandwidth_gbps = switch (self.active_backend) {
                .cuda => rust_ffi.get_cuda_memory_bandwidth(),
                .vulkan => rust_ffi.get_vulkan_memory_bandwidth(),
                .metal => rust_ffi.get_metal_memory_bandwidth(),
                .dx12 => rust_ffi.get_dx12_memory_bandwidth(),
                .webgpu => rust_ffi.get_webgpu_memory_bandwidth(),
                .cpu_fallback => 100.0, // Typical system RAM bandwidth
            },
            .compute_units = switch (self.active_backend) {
                .cuda => rust_ffi.get_cuda_compute_units(),
                .vulkan => rust_ffi.get_vulkan_compute_units(),
                .metal => rust_ffi.get_metal_compute_units(),
                .dx12 => rust_ffi.get_dx12_compute_units(),
                .webgpu => rust_ffi.get_webgpu_compute_units(),
                .cpu_fallback => @as(u32, @intCast(std.Thread.getCpuCount() catch 8)),
            },
        };
    }

    const BackendInfo = struct {
        active_backend: Backend,
        performance_tier: enum { minimal, low, medium, high },
        memory_bandwidth_gbps: f32,
        compute_units: u32,
    };
};
