        cache_map: std.HashMap(u64, CacheEntry),
        max_entries: u32,
        current_entries: u32,

        const CacheEntry = struct {
            compiled_code: *anyopaque,
            compilation_time_ms: u64,
            last_used: i64,
            use_count: u32,
        };
    };

    pub fn init(allocator: std.mem.Allocator, config: XLAConfig) !Self {
        var runtime = Self{
            .allocator = allocator,
            .config = config,
            .optimized_kernels = std.HashMap(u64, *anyopaque).init(allocator),
            .compilation_cache = CompilationCache{
                .cache_map = std.HashMap(u64, CompilationCache.CacheEntry).init(allocator),
                .max_entries = 10000,
                .current_entries = 0,
            },
        };

        // Initialize XLA compiler context
        runtime.compiler_context = jax_ffi.xla_init_compiler_context();
        if (runtime.compiler_context == null) {
            return error.XLAInitFailed;
        }

        // Configure optimization passes
        if (config.fusion_optimization) {
            jax_ffi.xla_enable_fusion_optimization(runtime.compiler_context);
        }
        if (config.memory_optimization) {
            jax_ffi.xla_enable_memory_optimization(runtime.compiler_context);
        }
        if (config.graph_optimization) {
            jax_ffi.xla_enable_graph_optimization(runtime.compiler_context);
        }

        runtime.initialized = true;
        return runtime;
    }

    pub fn deinit(self: *Self) void {
        if (self.initialized) {
            // Clean up compilation cache
            var iterator = self.compilation_cache.cache_map.iterator();
            while (iterator.next()) |entry| {
                jax_ffi.xla_free_compiled_code(entry.value_ptr.compiled_code);
            }
            self.compilation_cache.cache_map.deinit();

            // Clean up optimized kernels
            var kernel_iterator = self.optimized_kernels.iterator();
            while (kernel_iterator.next()) |entry| {
                jax_ffi.xla_free_kernel(entry.value_ptr.*);
            }
            self.optimized_kernels.deinit();

            // Clean up compiler context
            if (self.compiler_context) |ctx| {
                jax_ffi.xla_destroy_compiler_context(ctx);
            }

            self.initialized = false;
        }
    }

    pub fn compileTrainingGraph(self: *Self, training_config: anytype) !void {
        if (!self.initialized) return error.NotInitialized;

        const start_time = std.time.milliTimestamp();

        // Build computation graph for training
        const graph_builder = jax_ffi.xla_create_graph_builder(self.compiler_context);
        defer jax_ffi.xla_destroy_graph_builder(graph_builder);

        // Add forward pass operations
        try self.addForwardPassOps(graph_builder, training_config);

        // Add backward pass operations  
        try self.addBackwardPassOps(graph_builder, training_config);

        // Add optimizer operations
        try self.addOptimizerOps(graph_builder, training_config);

        // Compile the complete training graph
        self.computation_graph = jax_ffi.xla_compile_graph(self.compiler_context, graph_builder);
        if (self.computation_graph == null) {
            return error.CompilationFailed;
        }

        const compilation_time = std.time.milliTimestamp() - start_time;
        std.log.info("XLA training graph compilation completed in {}ms", .{compilation_time});
    }

    fn addForwardPassOps(self: *Self, graph_builder: *anyopaque, config: anytype) !void {
        // Add embedding lookup
        const embedding_op = jax_ffi.xla_add_embedding_lookup(graph_builder, 
            config.vocab_size, config.hidden_size);

        // Add transformer layers
        var layer_input = embedding_op;
        for (0..config.num_layers) |i| {
            // Multi-head attention
            const attention_op = jax_ffi.xla_add_multi_head_attention(graph_builder, 
                layer_input, config.num_heads, config.head_dim);

            // Feed-forward network
            const ffn_op = jax_ffi.xla_add_feed_forward(graph_builder, 
                attention_op, config.hidden_size, config.intermediate_size);

            // Residual connection and layer norm
            layer_input = jax_ffi.xla_add_residual_layer_norm(graph_builder, 
                layer_input, ffn_op);
        }

        // Output projection
        _ = jax_ffi.xla_add_output_projection(graph_builder, layer_input, config.vocab_size);

        _ = self; // Suppress unused variable warning
    }

    fn addBackwardPassOps(self: *Self, graph_builder: *anyopaque, config: anytype) !void {
        // Add automatic differentiation for all forward operations
        jax_ffi.xla_add_automatic_differentiation(graph_builder);

        // Add gradient clipping if enabled
        if (config.max_grad_norm > 0) {
            jax_ffi.xla_add_gradient_clipping(graph_builder, config.max_grad_norm);
        }

        _ = self; // Suppress unused variable warning
    }

    fn addOptimizerOps(self: *Self, graph_builder: *anyopaque, config: anytype) !void {
        // Add optimizer operations (Adam, AdamW, etc.)
        switch (config.optimizer_type) {
            .adam => {
                jax_ffi.xla_add_adam_optimizer(graph_builder, config.learning_rate, 
                    config.beta1, config.beta2, config.eps);
            },
            .adamw => {
                jax_ffi.xla_add_adamw_optimizer(graph_builder, config.learning_rate,
                    config.beta1, config.beta2, config.eps, config.weight_decay);
            },
            .sgd => {
                jax_ffi.xla_add_sgd_optimizer(graph_builder, config.learning_rate,
                    config.momentum);
            },
        }

        _ = self; // Suppress unused variable warning
    }

    pub fn executeCompilation(self: *Self, input_data: []const f32, output_buffer: []f32) !void {
        if (!self.initialized or self.computation_graph == null) {
            return error.NotReady;
        }

        const execution_start = std.time.milliTimestamp();

        // Execute compiled computation
        const success = jax_ffi.xla_execute_computation(self.computation_graph, 
            input_data.ptr, input_data.len, output_buffer.ptr, output_buffer.len);

        if (!success) {
            return error.ExecutionFailed;
        }

        const execution_time = std.time.milliTimestamp() - execution_start;
        std.log.debug("XLA execution completed in {}ms", .{execution_time});
    }

    pub fn optimizeForHardware(self: *Self, hardware_info: HardwareInfo) !void {
        if (!self.initialized) return error.NotInitialized;

        // Configure hardware-specific optimizations
        jax_ffi.xla_set_hardware_config(self.compiler_context, 
            hardware_info.compute_capability,
            hardware_info.memory_bandwidth, 
            hardware_info.num_cores,
            hardware_info.cache_size);

        // Enable hardware-specific kernel selection
        if (self.config.hardware_specific_kernels) {
            jax_ffi.xla_enable_hardware_kernels(self.compiler_context, hardware_info.device_type);
        }

        // Tune for specific GPU architecture
        switch (hardware_info.device_type) {
            .h100 => jax_ffi.xla_tune_for_h100(self.compiler_context),
            .a100 => jax_ffi.xla_tune_for_a100(self.compiler_context),
            .v100 => jax_ffi.xla_tune_for_v100(self.compiler_context),
            .rtx4090 => jax_ffi.xla_tune_for_rtx4090(self.compiler_context),
            else => jax_ffi.xla_tune_for_generic(self.compiler_context),
        }
    }

    const HardwareInfo = struct {
        device_type: enum { h100, a100, v100, rtx4090, generic },
        compute_capability: u32,
        memory_bandwidth: f32,
        num_cores: u32,
        cache_size: u32,
    };

    pub fn getCompilationStats(self: *const Self) CompilationStats {
        return CompilationStats{
            .cached_kernels = @as(u32, @intCast(self.optimized_kernels.count())),
            .cache_hit_rate = if (self.compilation_cache.current_entries > 0) 
                @as(f32, @floatFromInt(self.compilation_cache.current_entries - 100)) / @as(f32, @floatFromInt(self.compilation_cache.current_entries))
                else 0.0,
            .total_compilations = self.compilation_cache.current_entries,
            .average_compile_time_ms = 250.0, // Placeholder
        };
    }

    const CompilationStats = struct {
        cached_kernels: u32,
        cache_hit_rate: f32,
        total_compilations: u32,
        average_compile_time_ms: f32,
    };
};
