    pub fn optimizeMatrixMultiplication(self: *Self, M: u32, N: u32, K: u32,
                                       A: cuda.DevicePtr, B: cuda.DevicePtr, C: cuda.DevicePtr) !void {
        if (!self.initialized) return error.NotInitialized;

        // Use tile size optimized for H100 architecture
        const TILE_SIZE = 128;
        const WARP_SIZE = 32;

        const grid_dim = cuda.Dim3{
            .x = (N + TILE_SIZE - 1) / TILE_SIZE,
            .y = (M + TILE_SIZE - 1) / TILE_SIZE,
            .z = 1,
