            .y = (seq_len + BLOCK_SIZE_M - 1) / BLOCK_SIZE_M,
            .z = batch_size * num_heads,
        };

        const block_dim = cuda.Dim3{ .x = 32, .y = 4, .z = 1 };
        const shared_mem_size = (BLOCK_SIZE_M + BLOCK_SIZE_N) * head_dim * @sizeOf(f16);

        const params = [_]*anyopaque{
            @ptrCast(&Q), @ptrCast(&K), @ptrCast(&V), @ptrCast(&output),
            @ptrCast(&batch_size), @ptrCast(&seq_len), @ptrCast(&num_heads), @ptrCast(&head_dim)
        };

        try self.launchKernel("attention_compute", grid_dim, block_dim, &params, shared_mem_size);
