        var average_occupancy: f32 = 0.0;

        var time_iterator = self.performance_monitor.kernel_times.iterator();
        while (time_iterator.next()) |entry| {
            total_kernel_time += entry.value_ptr.*;
        }

        var occupancy_iterator = self.performance_monitor.occupancy_rates.iterator();
        var occupancy_count: u32 = 0;
        while (occupancy_iterator.next()) |entry| {
