            .total_kernel_time_ms = total_kernel_time,
            .average_occupancy = average_occupancy,
            .evolutionary_generations = if (self.evolutionary_optimizer) |opt| opt.generation_count else 0,
            .optimization_active = self.config.evolutionary_optimization,
