                .freed_bytes = 0,
                .collection_active = false,
            };
        }

        // Configure huge pages if enabled
        if (config.huge_pages) {
            try allocator.configureHugePages();
        }

        allocator.initialized = true;
        return allocator;
    }

    pub fn deinit(self: *Self) void {
        if (self.initialized) {
            // Clean up memory pools
            if (self.config.memory_pools) {
                for (self.memory_pools) |*pool| {
                    pool.free_list.deinit();
                    self.base_allocator.free(pool.blocks);
                }
                self.base_allocator.free(self.memory_pools);
            }

            // Clean up NUMA nodes
            if (self.config.numa_aware) {
