        // Fallback to base allocator
        const result = self.base_allocator.rawAlloc(len, ptr_align, ret_addr);
        if (result != null) {
            self.updateStats(len, true);
        }

        return result;
    }

    fn resize(ctx: *anyopaque, buf: []u8, buf_align: u8, new_len: usize, ret_addr: usize) bool {
        const self: *Self = @ptrCast(@alignCast(ctx));
        _ = buf_align;
        _ = ret_addr;

        if (!self.initialized) return false;

        // Try to resize within the same pool
        if (self.config.memory_pools) {
            const old_len = buf.len;
            if (self.canResizeInPool(buf.ptr, old_len, new_len)) {
                self.updateStats(new_len - old_len, new_len > old_len);
                return true;
            }
        }

        return self.base_allocator.rawResize(buf, buf_align, new_len, ret_addr);
    }

    fn free(ctx: *anyopaque, buf: []u8, buf_align: u8, ret_addr: usize) void {
        const self: *Self = @ptrCast(@alignCast(ctx));
        _ = buf_align;
        _ = ret_addr;

        if (!self.initialized) return;

        // Try to free to appropriate memory pool
        if (self.config.memory_pools) {
            if (self.freeToPool(buf.ptr, buf.len)) {
                self.updateStats(buf.len, false);
                return;
            }
        }

        // Fallback to base allocator
        self.base_allocator.rawFree(buf, buf_align, ret_addr);
        self.updateStats(buf.len, false);
    }

    fn allocateFromPool(self: *Self, size: usize) ?[*]u8 {
        // Find the best fitting pool
        for (self.memory_pools) |*pool| {
            if (size <= pool.block_size and pool.free_blocks > 0) {
                if (pool.free_list.popOrNull()) |ptr| {
                    pool.free_blocks -= 1;
                    pool.allocation_count += 1;
                    return @as([*]u8, @ptrCast(ptr));
                }
            }
        }
        return null;
    }

    fn freeToPool(self: *Self, ptr: *anyopaque, size: usize) bool {
        // Find the appropriate pool
        for (self.memory_pools) |*pool| {
            if (size <= pool.block_size) {
                // Verify the pointer belongs to this pool
                const pool_start = @intFromPtr(pool.blocks.ptr);
                const pool_end = pool_start + pool.blocks.len;
                const ptr_addr = @intFromPtr(ptr);

                if (ptr_addr >= pool_start and ptr_addr < pool_end) {
                    pool.free_list.append(ptr) catch return false;
                    pool.free_blocks += 1;
                    return true;
                }
            }
        }
        return false;
    }

    fn canResizeInPool(self: *Self, ptr: *anyopaque, old_size: usize, new_size: usize) bool {
        _ = self;
        _ = ptr;
        _ = old_size;
        _ = new_size;
        // Simplified: pools generally can't resize
        return false;
    }

    fn updateStats(self: *Self, size: usize, is_allocation: bool) void {
        if (is_allocation) {
            self.memory_stats.total_allocated += size;
            self.memory_stats.allocation_count += 1;
            if (self.memory_stats.total_allocated > self.memory_stats.peak_allocated) {
                self.memory_stats.peak_allocated = self.memory_stats.total_allocated;
            }
        } else {
            self.memory_stats.total_allocated = if (self.memory_stats.total_allocated >= size) 
                self.memory_stats.total_allocated - size else 0;
            self.memory_stats.deallocation_count += 1;
        }

        // Update fragmentation ratio
        self.memory_stats.fragmentation_ratio = self.calculateFragmentation();

        // Trigger garbage collection if needed
        if (self.garbage_collector != null and 
            self.memory_stats.total_allocated > self.garbage_collector.?.collection_threshold) {
            self.triggerGarbageCollection();
        }
    }

    fn calculateFragmentation(self: *const Self) f32 {
        if (!self.config.memory_pools) return 0.0;

        var total_free: usize = 0;
        var total_pools: usize = 0;

        for (self.memory_pools) |pool| {
            total_free += pool.free_blocks * pool.block_size;
            total_pools += pool.total_blocks * pool.block_size;
        }

        if (total_pools == 0) return 0.0;
        return 1.0 - (@as(f32, @floatFromInt(total_free)) / @as(f32, @floatFromInt(total_pools)));
    }

    fn triggerGarbageCollection(self: *Self) void {
        if (self.garbage_collector == null or self.garbage_collector.?.collection_active) return;

        self.garbage_collector.?.collection_active = true;
        const start_time = std.time.milliTimestamp();

        // Perform garbage collection
        var freed_bytes: usize = 0;

        // Compact memory pools
        for (self.memory_pools) |*pool| {
            // Simple defragmentation by rebuilding free list
            pool.free_list.clearRetainingCapacity();
            pool.free_blocks = 0;

            // Rebuild free list (this is a simplified version)
            var i: u32 = 0;
            while (i < pool.total_blocks) : (i += 1) {
                const block_ptr = @as(*anyopaque, @ptrCast(pool.blocks.ptr + i * pool.block_size));
                // In real implementation, would check if block is actually free
                pool.free_list.append(block_ptr) catch continue;
                pool.free_blocks += 1;
            }

            freed_bytes += pool.free_blocks * pool.block_size;
        }

        // Update GC stats
        const gc = self.garbage_collector.?;
        gc.total_collections += 1;
        gc.freed_bytes += freed_bytes;
        gc.last_collection = std.time.milliTimestamp();
        gc.collection_active = false;

        const collection_time = gc.last_collection - start_time;
        std.log.info("Garbage collection completed in {}ms, freed {}MB", 
            .{ collection_time, freed_bytes / (1024 * 1024) });
    }

    pub fn getCurrentUsage(self: *const Self) usize {
        return self.memory_stats.total_allocated;
