    pub fn getMemoryReport(self: *const Self) MemoryReport {
        var pool_utilization: f32 = 0.0;
        if (self.config.memory_pools) {
            var total_used: usize = 0;
            var total_capacity: usize = 0;

            for (self.memory_pools) |pool| {
                total_used += (pool.total_blocks - pool.free_blocks) * pool.block_size;
                total_capacity += pool.total_blocks * pool.block_size;
            }

            if (total_capacity > 0) {
                pool_utilization = @as(f32, @floatFromInt(total_used)) / @as(f32, @floatFromInt(total_capacity));
            }
        }

        return MemoryReport{
            .total_allocated_mb = @as(u32, @intCast(self.memory_stats.total_allocated / (1024 * 1024))),
            .peak_allocated_mb = @as(u32, @intCast(self.memory_stats.peak_allocated / (1024 * 1024))),
            .fragmentation_ratio = self.memory_stats.fragmentation_ratio,
            .pool_utilization = pool_utilization,
            .allocation_count = self.memory_stats.allocation_count,
            .gc_collections = if (self.garbage_collector) |gc| gc.total_collections else 0,
            .numa_nodes_active = if (self.config.numa_aware) @as(u32, @intCast(self.numa_nodes.len)) else 0,
        };
    }

