const std = @import("std");

pub const Logger = struct {
    allocator: std.mem.Allocator,
    config: LogConfig,
    file_handle: ?std.fs.File = null,
    console_enabled: bool,
    buffer: std.ArrayList(u8),
    mutex: std.Thread.Mutex,
    background_thread: ?std.Thread = null,
    message_queue: std.ArrayList(LogMessage),
    queue_mutex: std.Thread.Mutex,
    shutdown_requested: bool = false,
    start_time: i64,
    metrics: LogMetrics,
    initialized: bool = false,

    const Self = @This();

    pub const LogConfig = struct {
        level: LogLevel,
        output_file: []const u8,
        max_file_size: usize,
        rotation_enabled: bool,
    };

    pub const LogLevel = enum {
        debug,
        info,
        warn,
        error,
        fatal,

        fn toString(self: LogLevel) []const u8 {
            return switch (self) {
                .debug => "DEBUG",
                .info => "INFO",
                .warn => "WARN",
                .error => "ERROR",
                .fatal => "FATAL",
            };
        }

        fn toInt(self: LogLevel) u8 {
            return switch (self) {
                .debug => 0,
                .info => 1,
                .warn => 2,
                .error => 3,
                .fatal => 4,
            };
        }
    };

    pub const LogMessage = struct {
        level: LogLevel,
        timestamp: i64,
        thread_id: u32,
        message: []const u8,
        allocated: bool,
    };

    pub const LogMetrics = struct {
        total_messages: u64,
        messages_by_level: [5]u64,
        dropped_messages: u64,
        file_rotations: u32,
        current_file_size: usize,
    };

    pub fn init(allocator: std.mem.Allocator, config: LogConfig) !Self {
        var logger = Self{
            .allocator = allocator,
            .config = config,
            .console_enabled = true,
            .buffer = std.ArrayList(u8).init(allocator),
            .mutex = std.Thread.Mutex{},
            .message_queue = std.ArrayList(LogMessage).init(allocator),
            .queue_mutex = std.Thread.Mutex{},
            .start_time = std.time.milliTimestamp(),
            .metrics = LogMetrics{
                .total_messages = 0,
                .messages_by_level = [_]u64{0} ** 5,
                .dropped_messages = 0,
                .file_rotations = 0,
                .current_file_size = 0,
            },
        };

        // Open log file
        if (config.output_file.len > 0) {
            logger.file_handle = std.fs.cwd().createFile(config.output_file, .{
                .read = false,
                .truncate = false,
            }) catch |err| switch (err) {
                error.FileNotFound => try std.fs.cwd().createFile(config.output_file, .{}),
                else => return err,
            };
        }

        // Start background logging thread
        logger.background_thread = try std.Thread.spawn(.{}, backgroundWorker, .{&logger});

        logger.initialized = true;
        return logger;
    }

    pub fn deinit(self: *Self) void {
        if (self.initialized) {
            // Signal shutdown and wait for background thread
            self.shutdown_requested = true;
            if (self.background_thread) |thread| {
                thread.join();
            }

            // Process any remaining messages
            self.flushQueue();

            // Clean up resources
            if (self.file_handle) |handle| {
                handle.close();
            }

            // Clean up message queue
            self.queue_mutex.lock();
            for (self.message_queue.items) |msg| {
                if (msg.allocated) {
                    self.allocator.free(msg.message);
                }
            }
            self.message_queue.deinit();
            self.queue_mutex.unlock();

            self.buffer.deinit();
            self.initialized = false;
        }
    }

    fn backgroundWorker(self: *Self) void {
        while (!self.shutdown_requested) {
            self.flushQueue();
            std.time.sleep(10 * std.time.ns_per_ms); // 10ms interval
        }
    }

    fn flushQueue(self: *Self) void {
        self.queue_mutex.lock();
        defer self.queue_mutex.unlock();

        while (self.message_queue.items.len > 0) {
            const msg = self.message_queue.orderedRemove(0);
            self.writeMessage(msg);

            if (msg.allocated) {
                self.allocator.free(msg.message);
            }
        }
    }

    fn writeMessage(self: *Self, msg: LogMessage) void {
        self.mutex.lock();
        defer self.mutex.unlock();

        // Format timestamp
        const timestamp = msg.timestamp - self.start_time;
        const hours = timestamp / (1000 * 60 * 60);
        const minutes = (timestamp / (1000 * 60)) % 60;
        const seconds = (timestamp / 1000) % 60;
        const millis = timestamp % 1000;

        // Clear buffer and format message
        self.buffer.clearRetainingCapacity();
        self.buffer.writer().print("[{:02}:{:02}:{:02}.{:03}] [{s}] [T:{}] {s}\n", .{
            hours, minutes, seconds, millis,
            msg.level.toString(),
            msg.thread_id,
            msg.message,
        }) catch return;

        // Write to console if enabled
        if (self.console_enabled) {
            switch (msg.level) {
                .error, .fatal => std.io.getStdErr().writeAll(self.buffer.items) catch {},
                else => std.io.getStdOut().writeAll(self.buffer.items) catch {},
            }
        }

        // Write to file if configured
        if (self.file_handle) |handle| {
            handle.writeAll(self.buffer.items) catch {};
            self.metrics.current_file_size += self.buffer.items.len;

            // Check for file rotation
            if (self.config.rotation_enabled and 
                self.metrics.current_file_size > self.config.max_file_size) {
                self.rotateLogFile() catch {};
            }
        }

        // Update metrics
        self.metrics.total_messages += 1;
        self.metrics.messages_by_level[msg.level.toInt()] += 1;
    }

    fn rotateLogFile(self: *Self) !void {
        if (self.file_handle == null) return;

        self.file_handle.?.close();

        // Rename current log file
        const timestamp = std.time.milliTimestamp();
        const rotated_name = try std.fmt.allocPrint(self.allocator, "{s}.{}", .{ self.config.output_file, timestamp });
        defer self.allocator.free(rotated_name);

        std.fs.cwd().rename(self.config.output_file, rotated_name) catch {};

        // Create new log file
        self.file_handle = try std.fs.cwd().createFile(self.config.output_file, .{});

        self.metrics.file_rotations += 1;
        self.metrics.current_file_size = 0;
    }

    fn logWithLevel(self: *Self, level: LogLevel, comptime format: []const u8, args: anytype) void {
        if (!self.initialized or level.toInt() < self.config.level.toInt()) return;

        const message = std.fmt.allocPrint(self.allocator, format, args) catch {
            self.metrics.dropped_messages += 1;
            return;
        };

        const log_msg = LogMessage{
            .level = level,
            .timestamp = std.time.milliTimestamp(),
            .thread_id = std.Thread.getCurrentId(),
            .message = message,
            .allocated = true,
        };

        self.queue_mutex.lock();
        if (self.message_queue.items.len < 10000) { // Prevent unbounded growth
            self.message_queue.append(log_msg) catch {
                self.allocator.free(message);
                self.metrics.dropped_messages += 1;
            };
        } else {
            self.allocator.free(message);
            self.metrics.dropped_messages += 1;
        }
        self.queue_mutex.unlock();
    }

    pub fn debug(self: *Self, comptime format: []const u8, args: anytype) void {
        self.logWithLevel(.debug, format, args);
    }

    pub fn info(self: *Self, comptime format: []const u8, args: anytype) void {
        self.logWithLevel(.info, format, args);
    }

    pub fn warn(self: *Self, comptime format: []const u8, args: anytype) void {
        self.logWithLevel(.warn, format, args);
    }

    pub fn err(self: *Self, comptime format: []const u8, args: anytype) void {
        self.logWithLevel(.error, format, args);
    }

    pub fn fatal(self: *Self, comptime format: []const u8, args: anytype) void {
        self.logWithLevel(.fatal, format, args);
    }

    pub fn getUptime(self: *const Self) u64 {
        return @as(u64, @intCast((std.time.milliTimestamp() - self.start_time) / 1000));
    }

    pub fn getMetrics(self: *const Self) LogMetrics {
        return self.metrics;
    }
};
