    else
        echo -e "${RED}Error: CUDA not found, required for GPU acceleration${NC}"
        exit 1
    fi

    # Check for required compilers
    for compiler in zig rustc elixir julia; do
        if ! command -v $compiler &> /dev/null; then
            echo -e "${RED}Error: $compiler not found${NC}"
            exit 1
        fi
        echo "  $compiler: $(command -v $compiler)"
    done
}

