build_cuda_kernels() {
    echo -e "${BLUE}Building CUDA kernels...${NC}"

    CUDA_ARCH=${CUDA_ARCH:-sm_80,sm_86,sm_89,sm_90} # H100, A100, RTX 40xx support

    cd cuda_kernels/src

    for kernel_file in *.cu; do
        kernel_name="${kernel_file%.cu}"
        echo "  Compiling $kernel_name..."

        nvcc -O3 -gencode arch=compute_80,code=sm_80 \
