import jax
import jax.numpy as jnp
from jax import jit
import os

# Configure JAX for compilation
os.environ['XLA_FLAGS'] = '--xla_gpu_cuda_data_dir=/usr/local/cuda'

# Compile training graph
@jit
def training_step(params, inputs, targets):
    def loss_fn(params):
        predictions = forward_pass(params, inputs)
        return jnp.mean((predictions - targets) ** 2)

    grads = jax.grad(loss_fn)(params)
    return grads

def forward_pass(params, inputs):
    # Simplified forward pass
    return jnp.dot(inputs, params['weights']) + params['bias']

# Warm up compilation
dummy_params = {
